-- Generated from the source-owned connector catalogue and permission defaults.
-- Regenerate with tests/m14_03_operational_static_parity.mjs --write <new CLI migration>.
-- This does not create a table, duplicate credentials, or accept browser-supplied rows.
create or replace function public.m14_03_static_catalog_version() returns text language sql immutable
set search_path=public,pg_temp as $$ select '7cd77270de70e29b49a5c9c31e98adde1310b5b26b1271e7c7f459ebe48708ae'::text $$;
create or replace function public.m14_03_static_permissions_version() returns text language sql immutable
set search_path=public,pg_temp as $$ select '7f7a84dca68b5bfdab40b52e04e6fd7e61481ef5aeed0959f8d7104739eeee3c'::text $$;
create or replace function public.m14_03_static_catalog_rows() returns table(source_id text,source_version text,product_id uuid,row_values jsonb)
language sql immutable set search_path=public,pg_temp as $$
 select item->>'id',public.m14_03_static_catalog_version(),null::uuid,item
 from jsonb_array_elements('[{"id":"reference_conformance","name":"Reference conformance","implementation":"reference","phase":"V1","priority":"P0","canConfigure":true,"description":"Deterministic product and release fixtures for adapter conformance. No vendor network connection.","guidance":"Use disposable fixture credentials only. Scope introspection is not applicable; success validates fixtures rather than a vendor connection.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"not_applicable"},{"id":"github_actions","name":"GitHub and Actions","implementation":"ci","phase":"MVP","priority":"P0","canConfigure":true,"description":"CI build identity and SBOM intake; no product/release synchronization or passing gate policy.","guidance":"Use a least-privilege GitHub App limited to selected repositories with Actions read, Contents read for release tag proof, and Metadata read; never use a personal access token.","scopePolicyVersion":"2026-09-28.1","requiredScopes":["actions:read","contents:read","metadata:read"],"scopeIntrospection":"unavailable"},{"id":"gitlab_ci","name":"GitLab CI","implementation":"ci","phase":"V1","priority":"P0","canConfigure":true,"description":"CI build identity and SBOM intake; no product/release synchronization or passing gate policy.","guidance":"Use a dedicated project token and the minimum project permissions. Self-managed hosts require approved egress.","scopePolicyVersion":"2026-09-28.1","requiredScopes":["read_api"],"scopeIntrospection":"unavailable"},{"id":"azure_devops","name":"Azure DevOps","implementation":"ci","phase":"V1","priority":"P1","canConfigure":true,"description":"CI build identity and SBOM intake; no product/release synchronization or passing gate policy.","guidance":"Restrict the service connection to approved projects and pipelines. Azure DevOps Services only.","scopePolicyVersion":"2026-09-28.1","requiredScopes":["vso.build"],"scopeIntrospection":"unavailable"},{"id":"entra_id","name":"Microsoft Entra ID","implementation":"planned","phase":"V1","priority":"P0","canConfigure":false,"description":"Planned SAML identity assertions and groups; SCIM belongs to V2.","guidance":"Limit identity assertions and group mappings to the approved application. This catalogue does not replace existing identity providers. Matrix V1 scope is SAML; SCIM is V2.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"unavailable"},{"id":"okta","name":"Okta","implementation":"planned","phase":"V1","priority":"P0","canConfigure":false,"description":"Planned SAML identity assertions and groups; SCIM belongs to V2.","guidance":"Limit assertions and groups to the approved application. Matrix V1 scope is SAML; SCIM is V2. No hub-managed identity integration is available.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"unavailable"},{"id":"jira","name":"Jira","implementation":"ticketing","phase":"V1","priority":"P1","canConfigure":true,"description":"Loop-safe remediation ticket creation and status transition ingestion for Jira Cloud.","guidance":"Use a dedicated Jira Cloud API token with granular REST scopes and restrict the identity to selected projects with Browse, Create, Edit and Transition issue permissions. Do not grant site-wide administration.","scopePolicyVersion":"2026-09-28.1","requiredScopes":["read:application-role:jira","read:field:jira","read:field.default-value:jira","read:field.option:jira","read:group:jira","read:issue:jira","read:issue-details:jira","read:issue-meta:jira","read:issue-type:jira","read:issue.property:jira","read:issue.transition:jira","read:project:jira","read:project.property:jira","read:user:jira","write:issue:jira","write:issue.property:jira"],"scopeIntrospection":"unavailable"},{"id":"on_prem_agent","name":"On-premises agent","implementation":"agent","phase":"V2","priority":"P2","canConfigure":true,"description":"Outbound-only canonical product and release ingestion through a customer-hosted agent.","guidance":"Use a dedicated read-only source identity and approve only the required files or HTTPS hosts. Source privileges cannot be introspected by CRA; validate customer schemas and review each dry run before commit.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"unavailable"},{"id":"slack","name":"Slack","implementation":"planned","phase":"V1","priority":"P1","canConfigure":false,"description":"Planned alerts, countdown warnings and approval deep links.","guidance":"Limit bot or webhook access to approved channels. Approval actions must use authenticated application deep links, never chat identity as authorization.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"unavailable"},{"id":"teams","name":"Microsoft Teams","implementation":"planned","phase":"V1","priority":"P1","canConfigure":false,"description":"Planned alerts and prompts through a webhook or bot.","guidance":"Restrict delivery to approved teams and channels. Approval prompts use authenticated application deep links.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"unavailable"},{"id":"smtp","name":"SMTP","implementation":"planned","phase":"MVP","priority":"P0","canConfigure":false,"description":"Mail delivery already exists as platform infrastructure; hub-managed SMTP configuration is planned.","guidance":"Use a dedicated relay identity, transport encryption and restricted sender/recipient policy. Existing MailService configuration remains outside this hub.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"unavailable"},{"id":"s3","name":"S3-compatible object storage","implementation":"planned","phase":"MVP","priority":"P0","canConfigure":false,"description":"Artifact storage already exists as platform infrastructure; hub-managed S3 configuration is planned.","guidance":"Restrict storage identities to the required tenant bucket/prefix and operations. Existing Supabase storage adapters remain outside this hub.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"unavailable"},{"id":"servicenow","name":"ServiceNow","implementation":"planned","phase":"V2","priority":"P2","canConfigure":false,"description":"Planned incident/change creation and closure status ingestion through the Table API.","guidance":"Use a dedicated identity restricted to required tables and operations. Availability follows the integration foundation and approved routing.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"unavailable"},{"id":"teamcenter","name":"Teamcenter","implementation":"planned","phase":"V2","priority":"P2","canConfigure":false,"description":"Planned product structure, versions and lifecycle ingestion with compliance status export.","guidance":"Use the approved on-premises agent and a restricted integration identity only after validating the customer schema. No turnkey Teamcenter adapter or writeback is available.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"unavailable"},{"id":"windchill","name":"Windchill","implementation":"planned","phase":"V2","priority":"P2","canConfigure":false,"description":"Planned product structure, versions and lifecycle ingestion with compliance status export.","guidance":"Use the approved on-premises agent and minimum read permissions only after validating the customer schema. This catalogue does not duplicate the existing PLM integration ownership or offer writeback.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"unavailable"},{"id":"siem","name":"SIEM","implementation":"siem","phase":"V2","priority":"P2","canConfigure":true,"description":"Forward selected structural tenant audit events using authenticated HTTPS or TLS syslog in JSON or CEF.","guidance":"Configure through the dedicated SIEM surface with audit/export permissions and approved public collectors. Global security evidence and source contents are excluded.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"unavailable"},{"id":"enisa","name":"ENISA Single Reporting Platform","implementation":"planned","phase":"V2","priority":"P0","canConfigure":false,"description":"Automated staged report delivery and acknowledgements await confirmed official specifications.","guidance":"Use the existing signed manual export until official specifications and a supported transport are confirmed. No automated hub delivery is claimed.","scopePolicyVersion":"2026-09-28.1","requiredScopes":[],"scopeIntrospection":"unavailable"}]'::jsonb) with ordinality items(item,ordinal)
 order by ordinal
$$;
create or replace function public.m14_03_static_permission_rows(p_org uuid) returns table(source_id text,source_version text,product_id uuid,row_values jsonb)
language sql stable security definer set search_path=public,pg_temp as $$
 select r.item->>'permissionKey',public.m14_03_static_permissions_version(),null::uuid,
 jsonb_build_object('permissionKey',r.item->>'permissionKey',
  'owner',coalesce((o.permissions->> (r.item->>'permissionKey'))::boolean,(r.item->>'owner')::boolean),
  'admin',coalesce((a.permissions->> (r.item->>'permissionKey'))::boolean,(r.item->>'admin')::boolean),
  'member',coalesce((m.permissions->> (r.item->>'permissionKey'))::boolean,(r.item->>'member')::boolean),
  'viewer',coalesce((v.permissions->> (r.item->>'permissionKey'))::boolean,(r.item->>'viewer')::boolean))
